// Custom OpenNext entry point. Next.js route handlers cannot return a 101
// WebSocket upgrade response, so the upgrade is intercepted here before the
// generated OpenNext handler runs.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import openNextHandler from "./.open-next/worker.js";
import { RealtimeHub } from "./src/realtime/hub";
import { verifyRealtimeToken } from "./src/lib/realtime-token";
import type { CloudflareEnv } from "./src/lib/cloudflare-types";

export { RealtimeHub };

type OpenNextHandler = {
  fetch(request: Request, env: CloudflareEnv, ctx: unknown): Promise<Response>;
};

const handler = openNextHandler as unknown as OpenNextHandler;

function json(data: unknown, status: number): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json" },
  });
}

const worker = {
  async fetch(request: Request, env: CloudflareEnv, ctx: unknown): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/api/realtime/ws") {
      if (request.headers.get("upgrade")?.toLowerCase() !== "websocket") {
        return json({ error: "Expected a WebSocket upgrade" }, 426);
      }

      const secret = env.AUTH_SECRET ?? process.env.AUTH_SECRET;
      if (!secret) return json({ error: "Realtime is not configured" }, 503);

      const payload = await verifyRealtimeToken(url.searchParams.get("token"), secret);
      if (!payload) return json({ error: "Unauthorized" }, 401);

      // Lightweight Origin check. The signed token is the real credential, but
      // rejecting unknown browser origins avoids ambient cross-site upgrades.
      const origin = request.headers.get("origin");
      if (origin) {
        let originHost: string;
        try {
          originHost = new URL(origin).host;
        } catch {
          return json({ error: "Invalid origin" }, 403);
        }
        const requestHost = request.headers.get("x-forwarded-host") ?? request.headers.get("host");
        const allowed = new Set(
          [
            requestHost,
            env.APP_URL ? safeHost(env.APP_URL) : null,
          ].filter((value): value is string => Boolean(value)),
        );
        if (!allowed.has(originHost)) return json({ error: "Origin not allowed" }, 403);
      }

      const stub = env.REALTIME.get(env.REALTIME.idFromName(payload.org));
      // The Durable Object verifies the token again and derives identity from it.
      return stub.fetch(request);
    }

    return handler.fetch(request, env, ctx);
  },
};

export default worker;

function safeHost(url: string): string | null {
  try {
    return new URL(url).host;
  } catch {
    return null;
  }
}
